data.minimal_example:
final oss = OSSClient(
  OSSConfig.static(
    endpoint: 'your-endpoint.aliyuncs.com',
    region: 'your-region',
    accessKeyId: 'your-access-key-id',
    accessKeySecret: 'your-access-key-secret',
    bucketName: 'your-bucket-name',
  ),
);
await oss.putObject(File('path/to/file.txt'), 'example/file.txt');
